# Let me verify the "gap fill uses later non-zero's value" hypothesis
# by checking multiple columns in DEMO

def check_gap_fill(demo_input, demo_output, col):
    in_nz = [(r, demo_input[r][col]) for r in range(17) if demo_input[r][col] != 0]
    out_vals = [demo_output[r][col] for r in range(17)]

    print(f"\nCol {col}:")
    print(f"  Input non-zeros: {in_nz}")
    print(f"  Output: {out_vals}")

    for i in range(17):
        if demo_input[i][col] == 0:
            if demo_output[i][col] != 0:
                # This row was filled
                # Find which "gap" it belongs to
                in_rows = [r for r, v in in_nz]
                if in_rows:
                    # Find gap index
                    gap_idx = 0
                    for j in range(len(in_rows) - 1):
                        if in_rows[j] < i and in_rows[j+1] > i:
                            gap_idx = j + 1  # This gap is after in_rows[gap_idx-1], before in_rows[gap_idx]
                            break

                    if gap_idx < len(in_nz) - 1:
                        fill_value = out_vals[in_rows[gap_idx]]
                        print(f"  Row {i}: filled with {out_vals[i]}, which equals row {in_rows[gap_idx]} (value {fill_value})" if out_vals[i] == fill_value else f"  Row {i}: filled with {out_vals[i]}, but row {in_rows[gap_idx]} has {fill_value}")
                    elif gap_idx == len(in_nz) - 1:
                        fill_value = out_vals[in_rows[gap_idx]]
                        print(f"  Row {i}: filled with {out_vals[i]}, which equals row {in_rows[gap_idx]} (value {fill_value})" if out_vals[i] == fill_value else f"  Row {i}: filled with {out_vals[i]}, but row {in_rows[gap_idx]} has {fill_value}")

# Check various columns
for col in [1, 5, 8, 10, 14]:
    check_gap_fill(demo_input, demo_output, col)

# Check what columns DON'T fill (non-fill rule validation)
print("\n\n=== Non-fill validation ===")
print("Which demo columns did NOT change?")
for col in range(17):
    if demo_output[col] != demo_input[col]:
        print(f"  Col {col}: CHANGED")
    else:
        print(f"  Col {col}: unchanged")
